// Words Layer loader — lazy access to the JMdict common-words database
// generated by scripts/build-wordsdb.mjs into public/data/wordsdb/.
//
// Layout (see docs/19-Words-Database.md for the full spec):
//   words/words-{bb}.json   entry shards; bb = first two digits of the
//                           zero-padded JMdict id
//   kanji-words.json        kanji char -> [word ids] in the build's
//                           documented heuristic order (common form first,
//                           then shorter form, then kana)
//   accents.json            "writtenForm|kana" -> Kanjium pitch-accent
//                           pattern string (verbatim, e.g. "0", "2", "3,1")
//   search-index.json       compact rows [id, kanjiForms/'/', kana, gloss0]
//   manifest.json           sources, licences, counts, ordering rule
//
// Accents come from Kanjium; a word with no Kanjium line returns an honest
// null from getAccent — never a guessed pattern.

import { kanaToRomaji } from './kanjiDb.js'

const BASE = '/data/wordsdb'

// ------------------------------------------------------------- shard maths
export function wordShardFor(id) {
  return String(id).padStart(7, '0').slice(0, 2)
}
export function wordShardPath(id) {
  return `${BASE}/words/words-${wordShardFor(id)}.json`
}

// ------------------------------------------------------------------ caches
const shardCache = new Map()
function fetchShard(path) {
  if (!shardCache.has(path)) {
    shardCache.set(
      path,
      fetch(path).then((r) => (r.ok ? r.json() : null)).catch(() => null),
    )
  }
  return shardCache.get(path)
}
let kanjiWordsPromise = null
let accentsPromise = null
let searchIndexPromise = null
let manifestPromise = null

export function loadKanjiWords() {
  if (!kanjiWordsPromise) {
    kanjiWordsPromise = fetch(`${BASE}/kanji-words.json`)
      .then((r) => (r.ok ? r.json() : {}))
      .catch(() => ({}))
  }
  return kanjiWordsPromise
}

export function loadAccents() {
  if (!accentsPromise) {
    accentsPromise = fetch(`${BASE}/accents.json`)
      .then((r) => (r.ok ? r.json() : {}))
      .catch(() => ({}))
  }
  return accentsPromise
}

export function loadWordSearchIndex() {
  if (!searchIndexPromise) {
    searchIndexPromise = fetch(`${BASE}/search-index.json`)
      .then((r) => (r.ok ? r.json() : []))
      .catch(() => [])
  }
  return searchIndexPromise
}

export function loadWordsManifest() {
  if (!manifestPromise) {
    manifestPromise = fetch(`${BASE}/manifest.json`)
      .then((r) => (r.ok ? r.json() : null))
      .catch(() => null)
  }
  return manifestPromise
}

// ------------------------------------------------------------------ entries
/** One normalised entry {id, kanji, kana, gloss, common} or null. */
export async function getWord(id) {
  const shard = await fetchShard(wordShardPath(id))
  return shard?.[String(id)] || null
}

/**
 * Words containing the kanji, in the build's heuristic order (see the
 * manifest's ordering note), resolved to full entries.
 */
export async function wordsForKanji(char, limit = 10) {
  const map = await loadKanjiWords()
  const ids = (map[char] || []).slice(0, limit)
  const out = []
  for (const id of ids) {
    const entry = await getWord(id)
    if (entry) out.push(entry)
  }
  return out
}

/** The written form to display: prefer one containing `char`. */
export function wordDisplayForm(entry, char = null) {
  if (!entry) return ''
  if (char) {
    const hit = (entry.kanji || []).find((f) => f.includes(char))
    if (hit) return hit
  }
  return entry.kanji?.[0] || entry.kana || ''
}

// ------------------------------------------------------------------ accents
/**
 * Pure accent lookup over a loaded accents map. Tries each written form
 * with the entry's kana reading, then the kana-as-written-form key (the
 * shape kana-only words take in Kanjium). Returns the verbatim Kanjium
 * pattern string or null.
 */
export function accentForEntry(accents, entry) {
  if (!accents || !entry) return null
  const forms = entry.kanji?.length ? entry.kanji : [entry.kana]
  for (const form of forms) {
    const hit = accents[`${form}|${entry.kana}`]
    if (hit != null) return hit
  }
  return accents[`${entry.kana}|${entry.kana}`] ?? null
}

export async function getAccent(entry) {
  const accents = await loadAccents()
  return accentForEntry(accents, entry)
}

// ------------------------------------------------------------------- search
const HIRA_TO_KATA = (s) => String(s || '').replace(/[ぁ-ん]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 0x60))

/**
 * Pure search over search-index rows [id, kanjiForms/'/', kana, gloss0].
 * Rank order: exact written form or reading; written form containing the
 * query; reading prefix / romaji; first-gloss substring (Latin queries).
 * Returns rows, best first.
 */
export function searchWordIndex(rows, query, limit = 30) {
  const q = String(query || '').trim()
  if (!q) return []
  const qKata = HIRA_TO_KATA(q)
  const qLower = q.toLowerCase()
  const isLatin = /^[a-z][a-z\s'-]*$/.test(qLower)
  const hits = []
  for (const row of rows) {
    const [id, forms, kana, gloss0] = row
    let score = -1
    if (forms.split('/').includes(q) || kana === q) score = 0
    else if (q.length >= 1 && forms.includes(q)) score = 1
    if (score < 0 && /[ぁ-んァ-ヶ]/.test(q)) {
      if (HIRA_TO_KATA(kana).startsWith(qKata)) score = 2
      else if (HIRA_TO_KATA(kana).includes(qKata)) score = 3
    }
    if (score < 0 && isLatin) {
      const romaji = kanaToRomaji(kana)
      if (romaji === qLower) score = 2
      else if (romaji.startsWith(qLower)) score = 3
      else if (String(gloss0 || '').toLowerCase().includes(qLower)) score = 4
    }
    if (score >= 0) hits.push({ score, row })
  }
  hits.sort((a, b) => a.score - b.score || a.row[0] - b.row[0])
  return hits.slice(0, limit).map((h) => h.row)
}

/** Search the common-words index and resolve hits to full entries. */
export async function searchWords(query, limit = 30) {
  const rows = await loadWordSearchIndex()
  const hits = searchWordIndex(rows, query, limit)
  const out = []
  for (const [id] of hits) {
    const entry = await getWord(id)
    if (entry) out.push(entry)
  }
  return out
}
